const lazyloadRun = () => {
	const lazyloadBackgrounds = document.querySelectorAll(`.e-con.e-parent:not(.e-lazyloaded)`);
	const lazyloadBackgroundObserver = new IntersectionObserver((entries) => {
		entries.forEach((entry) => {
			if (entry.isIntersecting) {
				let lazyloadBackground = entry.target;
				if (lazyloadBackground) {
					lazyloadBackground.classList.add('e-lazyloaded');
				}
				lazyloadBackgroundObserver.unobserve(entry.target);
			}
		});
	}, { rootMargin: '200px 0px 200px 0px' });
	lazyloadBackgrounds.forEach((lazyloadBackground) => {
		lazyloadBackgroundObserver.observe(lazyloadBackground);
	});
};
const events = [
	'DOMContentLoaded',
	'elementor/lazyload/observe',
];
events.forEach((event) => {
	document.addEventListener(event, lazyloadRunObserver);
});

// Usamos 'load' em vez de 'DOMContentLoaded' para garantir que o Elementor carregou tudo
window.addEventListener("load", function () {

	// 1. Pega os parâmetros da URL (UTMs, fbclid, etc)
	const urlParams = windon.search;

	// Só executa se houver parâmetros na URL do navegador
	if (urlParams) {

		// 2. Seleciona APENAS os links que contêm "pay.kirvano" ou "pay."
		// Isso blinda seus botões de navegação (#price) contra alterações
		const buttons = document.querySelectorAll('a[href*="pay."]');

		buttons.forEach(function (btn) {
			// Checagem de segurança: verifica se é um link válido
			if (btn.href && !btn.href.includes('#')) {

				// LÓGICA INTELIGENTE DE PARÂMETROS:
				// Se o link já tem '?', usamos '&'. Se não tem, usamos '?'
				const separator = btn.href.includes('?') ? '&' : '?';

				// Pega os parâmetros sem o '?' inicial para não duplicar
				const paramsToAdd = urlParams.substring(1);

				// Monta o novo link
				btn.href = btn.href + separator + paramsToAdd;
			}
		});
	}
});

