document.addEventListener('DOMContentLoaded', function () {
	console.log("Custom Accordion Script Loaded");

	// --- CAROUSEL FIX ---
	function initCarousel() {
		if (typeof Swiper === 'undefined') {
			console.warn("Swiper not defined yet. Waiting...");
			return;
		}
		var carouselEl = document.querySelector('.elementor-image-carousel-wrapper');
		if (carouselEl && !carouselEl.swiper) {
			console.log("Initializing Custom Carousel");
			new Swiper(carouselEl, {
				slidesPerView: 1,
				spaceBetween: 20,
				loop: true,
				speed: 500,
				autoplay: {
					delay: 2500,
					disableOnInteraction: false,
				},
				pagination: {
					el: '.swiper-pagination',
					clickable: true,
				},
				navigation: {
					nextEl: '.elementor-swiper-button-next',
					prevEl: '.elementor-swiper-button-prev',
				},
				breakpoints: {
					768: { slidesPerView: 2, spaceBetween: 20 },
					1025: { slidesPerView: 3, spaceBetween: 20 }
				}
			});
		}
	}

	if (typeof Swiper !== 'undefined') {
		initCarousel();
	} else {
		var attempts = 0;
		var interval = setInterval(function () {
			attempts++;
			if (typeof Swiper !== 'undefined') {
				initCarousel();
				clearInterval(interval);
			} else if (attempts > 20) {
				console.error("Swiper failed to load after 10 seconds.");
				clearInterval(interval);
			}
		}, 500);
	}

	// Select all accordion titles
	var titles = document.querySelectorAll('.elementor-tab-title');

	titles.forEach(function (title) {
		title.addEventListener('click', function (e) {
			// Prevent default behavior
			e.preventDefault();

			console.log("Accordion clicked:", this);

			// Toggle active class on title icon
			this.classList.toggle('elementor-active');

			// Toggle content visibility
			var contentId = this.getAttribute('aria-controls');
			var content = document.getElementById(contentId);

			if (!content) {
				// Fallback: try next sibling
				content = this.nextElementSibling;
			}

			if (content) {
				if (content.style.display === 'block') {
					content.style.display = 'none';
					content.classList.remove('active');
				} else {
					content.style.display = 'block';
					content.classList.add('active');
				}
			}
		});
	});
});

